	{(assemblyKind != null ? $@"""assemblies"": [ ""{(assemblyKind != null ? AssemblyKindStrings[assemblyKind.Value] : "")}"" ]," : "")}
	{(baselineVersion != null ? $@"""baselineVersion"": ""{baselineVersion}""," : "")}
    ""includeTypes"": [ {string.Join(", ", typesToInclude.Select(x => $@"""{x}"""))} ],
    ""useFoldersInFilePaths"": {(useFoldersInFilePaths.Value ? "true" : "false")},
    ""useInternalAccessibility"": {(useInternalAccessibility ? "true" : "false")}
}}";
        test.TestState.AdditionalFiles.Add(("CodeAnalysis.Lightup.json", configFileContent));

        return test;
    }

    private static ReferenceAssemblies CreateReferenceAssemblies(bool includeValueTaskSupport = true)
    {
        // NOTE: Microsoft.CodeAnalysis (as of 2.9.0) itself depends on System.Threading.Tasks.Extensions on netstandard2.0/1.3,
        // so ValueTask<T> ends up available regardless of the base ReferenceAssemblies unless an older package version is used.
        var baseAssemblies = includeValueTaskSupport
            ? ReferenceAssemblies.Net.Net90
            : ReferenceAssemblies.NetStandard.NetStandard20;
        var packageVersion = includeValueTaskSupport ? "3.0.0" : "1.3.2";
        return baseAssemblies
            .AddPackages([new PackageIdentity("Microsoft.CodeAnalysis", packageVersion)]);
    }
}
